/**
 * Logo resmi sekolah Skoolia (Base64 PNG)
 * Digunakan untuk kop laporan cetak (Excel & PDF)
 */

/**
 * Logo Sekolah 1: SMP Negeri 1 Skoolia (Emblem Navy Gold)
 */
export const SCHOOL_1_LOGO_BASE64 =
  'data:image/png;base64,'

/**
 * Logo Sekolah 2 / 10: SMP Negeri 10 Skoolia (Emblem Emerald Teal Gold)
 */
export const SCHOOL_10_LOGO_BASE64 =
  'data:image/png;base64,'

/**
 * Mendapatkan logo sekolah sesuai ID atau Nama Sekolah aktif.
 * Default ke Logo SMP Negeri 1 Skoolia.
 */
export function getSchoolLogoBase64(
  sekolahId?: number | null,
  sekolahNama?: string | null
): string {
  if (sekolahId === 10 || (sekolahNama && /10/.test(sekolahNama))) {
    return SCHOOL_10_LOGO_BASE64
  }
  return SCHOOL_1_LOGO_BASE64
}

/**
 * Fallback default logo sekolah
 */
export const SCHOOL_LOGO_BASE64 = SCHOOL_1_LOGO_BASE64
